// Cari istilah berdasarkan id
export const istilahById = Object.fromEntries(glosarium.map((g) => [g.id, g]))

// Semua bentuk penulisan → id istilah (untuk mendeteksi istilah di teks materi)
const bentuk = []
for (const g of glosarium) {
  if (g.umum) continue
  const nama = [g.istilah.replace(/\s*\(.*?\)\s*/g, ' ').trim(), ...g.alias]
  for (const n of nama) if (n.length >= 2) bentuk.push([n, g.id])
}
bentuk.sort((a, b) => b[0].length - a[0].length)
const peta = new Map(bentuk.map(([n, id]) => [n.toLowerCase(), id]))
const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
export const polaIstilah = new RegExp(`(?<![\\p{L}\\d_-])(${bentuk.map(([n]) => escape(n)).join('|')})(?![\\p{L}\\d_-])`, 'giu')
export const idDariTeks = (teks) => peta.get(teks.toLowerCase())

// Istilah apa saja yang muncul di sebuah teks (urut sesuai kemunculan, tanpa duplikat)
export function istilahDalam(teks) {
  const hasil = []
  for (const m of String(teks).matchAll(polaIstilah)) {
    const id = idDariTeks(m[1])
    if (id && !hasil.includes(id)) hasil.push(id)
  }
  return hasil
}
